fn export_content(c:&Json)->String{obj(vec![("schema",Num("1".into())),("type",s("question_process")),("data",normalized(c)),("meaning",s("Question process export: authored plans/findings, actual returned-output receipts and finite comparisons"))]).string()}
fn export_format(value:&Json)->Result<&str>{match get(value,"format"){Null=>Ok("journal"),Str(v)if v=="journal"||v=="design_brief"=>Ok(v),_=>Err("Choose complete journal or design brief export".into())}}
fn export_document(c:&Json,value:&Json)->Result<String>{if export_format(value)?=="design_brief"{design_brief::content(c)}else{Ok(export_content(c))}}
struct Export{format:String,case:String,scope:Json,case_hash:String,path:String,content_hash:String,policy:String,valid:std::sync::Arc<std::sync::atomic::AtomicBool>,claimed:bool,created:Instant,model:bool}
static EXPORTS:OnceLock<Mutex<BTreeMap<String,Export>>>=OnceLock::new();
fn exports()->&'static Mutex<BTreeMap<String,Export>>{EXPORTS.get_or_init(||Mutex::new(BTreeMap::new()))}
fn forget_export(st:&mut Json){let key=text(st,"inquiry_export_active");if !key.is_empty(){if let Ok(mut all)=exports().lock(){if all.get(&key).is_some_and(|e|e.scope==identity(st)){if let Some(e)=all.remove(&key){e.valid.store(false,std::sync::atomic::Ordering::Release);}}}}put(st,"inquiry_export_active",Null);}
pub(super) fn reconcile(st:&Json){if let Ok(mut all)=exports().lock(){all.retain(|_,e|{let valid=e.created.elapsed()<Duration::from_secs(120)&&(e.scope!=identity(st)||find(st,&e.case,e.model).map(|c|harness_rules::digest(&normalized(&c))==e.case_hash).unwrap_or(false));if !valid{e.valid.store(false,std::sync::atomic::Ordering::Release);}valid});}}
pub(super) fn approve_export(st:&mut Json,p:&mut Json,model:bool)->Result<()>{
 let binding=get(p,"inquiry_export");if binding==&Null{return Ok(());}if text(p,"tool")!="write"||get(binding,"schema")!=&Num("1".into()){return Err("Invalid question export binding".into());}harness_rules::check(st,"hypotheses",&obj(vec![("process",obj(vec![("action",s("current"))]))]),model)?;if model{harness::allowed_tool(st,&obj(vec![("tool",s("hypotheses")),("args",obj(vec![]))]))?;}
 let id=text(binding,"id");let c=find(st,&id,model)?;let format=export_format(binding)?.to_string();let content=export_document(&c,binding)?;let args=get(p,"args");let hash=harness_rules::sha256(content.as_bytes());if text(args,"content")!=content||text(binding,"sha256")!=hash{return Err("Question data or returned evidence changed since export review; request a new export".into());}
 forget_export(st);static SERIAL:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(1);let n=SERIAL.fetch_update(std::sync::atomic::Ordering::Relaxed,std::sync::atomic::Ordering::Relaxed,|n|n.checked_add(1)).map_err(|_|"Export identity exhausted")?;let token=format!("question-export-{}-{n}",now());let current=harness_rules::gateway_current(&Null)?;let mut all=exports().lock().map_err(|_|"Question export ownership unavailable")?;all.retain(|_,e|{let valid=e.created.elapsed()<Duration::from_secs(120);if !valid{e.valid.store(false,std::sync::atomic::Ordering::Release);}valid});if all.len()>=32{return Err("Current question export allowance reached; ordinary writes remain available".into());}
 all.insert(token.clone(),Export{format:format.clone(),case:id.clone(),scope:identity(st),case_hash:harness_rules::digest(&normalized(&c)),path:text(args,"path"),content_hash:hash.clone(),policy:harness_rules::digest(&current),valid:std::sync::Arc::new(std::sync::atomic::AtomicBool::new(true)),claimed:false,created:Instant::now(),model});drop(all);put(st,"inquiry_export_active",s(&token));put(p,"inquiry_export",obj(vec![("schema",Num("1".into())),("id",s(&id)),("sha256",s(&hash)),("format",s(&format)),("token",s(&token))]));Ok(())
}
pub(super) struct ExportLease{token:String,valid:std::sync::Arc<std::sync::atomic::AtomicBool>,policy:String,cancellation:u64,deadline:Instant}
impl ExportLease{pub(super) fn check(&self)->Result<()>{let current=harness_rules::gateway_current(&Null)?;if !self.valid.load(std::sync::atomic::Ordering::Acquire)||Instant::now()>=self.deadline||super::super::execution::token_cancelled(self.cancellation)||harness_rules::digest(&current)!=self.policy{return Err("Question export source authority changed or export was interrupted; any new file remains unconfirmed".into());}Ok(())}}
impl Drop for ExportLease{fn drop(&mut self){if let Ok(mut all)=exports().lock(){if all.get(&self.token).is_some_and(|e|std::sync::Arc::ptr_eq(&e.valid,&self.valid)){all.remove(&self.token);}}}}
pub(super) fn worker_export(root:&Path,v:&Json,access:&operation::InspectionAccess)->Result<Option<ExportLease>>{
 let binding=get(v,"inquiry_export");if binding==&Null{return Ok(None);}if text(v,"tool")!="write"||access.root_identity.is_none(){return Err("Question export requires its current reviewed write operation".into());}let token=text(binding,"token");let mut all=exports().lock().map_err(|_|"Question export ownership unavailable")?;let e=all.get_mut(&token).ok_or("Question export was cancelled, expired, revoked or belongs to another process")?;let args=get(v,"args");if export_format(binding)?!=e.format||e.claimed||e.created.elapsed()>=Duration::from_secs(120)||text(binding,"id")!=e.case||text(binding,"sha256")!=e.content_hash||text(args,"path")!=e.path||harness_rules::sha256(text(args,"content").as_bytes())!=e.content_hash||text(&e.scope,"workspace")!=root.to_string_lossy(){return Err("Question export differs from its approved source or output".into());}e.claimed=true;let lease=ExportLease{token,valid:e.valid.clone(),policy:e.policy.clone(),cancellation:access.cancellation_token,deadline:access.deadline};drop(all);lease.check()?;Ok(Some(lease))
}

// Item assessments remain authored interpretation, bound to an exact plan revision.
fn plan_items(c:&Json)->Vec<(&'static str,usize,Json)>{let mut out=vec![];for collection in ["questions","requirements"]{for(i,value)in array(get(c,"plan"),collection).into_iter().enumerate(){out.push((collection,i+1,value));}}out}
fn assessment_refs(a:&Json,key:&str,count:usize)->Result<Vec<Json>>{if get(a,key)==&Null{return Ok(vec![]);}let values=get(a,key).array()?.clone();if values.len()>16||values.iter().any(|v|integer(v).ok().is_none_or(|n|n==0||n>count)){return Err(format!("{key} must reference at most16 actual retained records in this question"));}Ok(values)}
fn assessment_plan(c:&Json,digest:&str)->Option<Json>{let plan=get(c,"plan");if plan!=&Null&&harness_rules::digest(plan)==digest{return Some(plan.clone());}array(c,"notes").into_iter().filter(|v|text(v,"kind")=="previous_plan").map(|v|get(&v,"plan").clone()).find(|v|harness_rules::digest(v)==digest)}
fn valid_assessments(c:&Json)->bool{if get(c,"assessments")==&Null{return true;}let Ok(rows)=get(c,"assessments").array()else{return false;};if rows.len()>32{return false;}for(i,r)in rows.iter().enumerate(){if get(r,"id")!=&Num((i+1).to_string())||!hash(get(r,"plan_sha256"))||!["questions","requirements"].contains(&text(r,"item").as_str())||!["answered","partial","unresolved"].contains(&text(r,"status").as_str())||!matches!(get(r,"explanation"),Str(t)if !t.trim().is_empty()&&t.len()<=8192&&!t.contains('\0')){return false;}let Some(plan)=assessment_plan(c,&text(r,"plan_sha256"))else{return false;};let Ok(index)=integer(get(r,"index"))else{return false;};let items=array(&plan,&text(r,"item"));if index==0||index>items.len()||get(r,"item_text")!=&items[index-1]||assessment_refs(r,"citations",array(c,"evidence").len()).is_err()||assessment_refs(r,"checks",array(c,"checks").len()).is_err(){return false;}}true}
fn latest_assessment(c:&Json,collection:&str,index:usize)->Json{let digest=harness_rules::digest(get(c,"plan"));array(c,"assessments").into_iter().rev().find(|r|text(r,"plan_sha256")==digest&&text(r,"item")==collection&&number(r,"index")==index).unwrap_or(Null)}
fn review_counts(c:&Json)->Json{let mut counts=[0usize;4];let items=plan_items(c);for(collection,index,_)in &items{let a=latest_assessment(c,collection,*index);let slot=match text(&a,"status").as_str(){"answered"=>0,"partial"=>1,"unresolved"=>2,_=>3};counts[slot]+=1;}obj(vec![("planned_items",Num(items.len().to_string())),("authored_answered",Num(counts[0].to_string())),("authored_partial",Num(counts[1].to_string())),("authored_unresolved",Num(counts[2].to_string())),("unreviewed",Num(counts[3].to_string())),("meaning",s("Authored assessment counts for the current plan. Review each item against its linked observations and results."))])}
fn review_items(c:&Json,cap:usize)->Vec<Json>{plan_items(c).into_iter().map(|(collection,index,value)|{let a=latest_assessment(c,collection,index);let text_value=value.text().unwrap_or("");let checks=array(&a,"checks").into_iter().filter_map(|id|array(c,"checks").into_iter().find(|k|get(k,"id")==&id).map(|k|obj(vec![("id",id),("verdict",s(assess(c,&k))),("meaning",s("Finite comparison of actual returned text only"))]))).collect();obj(vec![("item",s(collection)),("index",Num(index.to_string())),("text",s(&clip(text_value,cap))),("display_truncated",Bool(text_value.len()>cap)),("status",if a==Null{s("unreviewed")}else{get(&a,"status").clone()}),("assessment",preview(&a,cap)),("referenced_checks",Arr(checks))])}).collect()}
fn record_assessment(c:&mut Json,a:&Json,origin:&str)->Result<()>{let plan=get(c,"plan");if plan==&Null||!hash(get(a,"plan_sha256"))||text(a,"plan_sha256")!=harness_rules::digest(plan){return Err("The plan changed or no exact plan identity was supplied; review its current items first".into());}let collection=text(a,"item");if !["questions","requirements"].contains(&collection.as_str()){return Err("Choose questions or requirements".into());}let items=array(plan,&collection);let index=integer(get(a,"index"))?;if index==0||index>items.len(){return Err("Choose an existing planned item number, starting at1".into());}let status=text(a,"status");if !["answered","partial","unresolved"].contains(&status.as_str())||text(a,"explanation").trim().is_empty(){return Err("Choose answered/partial/unresolved and explain the evidence or remaining gap".into());}let citations=assessment_refs(a,"citations",array(c,"evidence").len())?;let checks=assessment_refs(a,"checks",array(c,"checks").len())?;append_row(c,"assessments",obj(vec![("plan_sha256",get(a,"plan_sha256").clone()),("item",s(&collection)),("index",Num(index.to_string())),("item_text",items[index-1].clone()),("status",s(&status)),("explanation",get(a,"explanation").clone()),("citations",Arr(citations)),("checks",Arr(checks)),("origin",s(origin)),("meaning",s("Authored assessment of the exact plan item, not measured proof or an execution result"))]),32)?;Ok(())}

fn plan_display(st:&Json)->String{find(st,&selected(st),false).map(|c|plan_items(&c).iter().map(|(kind,index,value)|{let body=value.text().unwrap_or("");format!("{} {index}: {}{}",if *kind=="questions"{"Question"}else{"Requirement"},clip(body,256),if body.len()>256{" [preview shortened]"}else{""})}).collect::<Vec<_>>().join("\n")).unwrap_or_else(|e|e)}
